"""Writes the starting view the app ships, src/learner-start.ts, from the models fit.py wrote (ADR 0026).

    uv run ship.py --models models.json --miss S1-m100 --pace S1-p500 --rate-pair 0.0340 --rate-key 0.0386 --out ../src/learner-start.ts
"""

import argparse
import json

THOUSANDTHS = 1000
HEADER = """// Generated by ml/ship.py from the training participants of the public 136M Keystrokes dataset (Dhakal, Feit,
// Kristensson and Oulasvirta, CHI 2018). Do not edit: refit and rewrite it (docs/ml-data-evaluation.md, ADR 0026).
// Nothing here comes from a Stilltype user.

// The training participants' first-try miss rate on a pair, and on a key at the start of a word.
export const START_RATE = { pair: %s, key: %s };

const THOUSANDTHS = 1000;

// Per unit, in thousandths: what is added to the log odds its miss rate is pulled toward, and for a pair the log
// slowdown its pace is pulled toward. A unit the training participants never typed has no row.
const ROWS = `
%s
`;

export const START_TABLE = Object.fromEntries(ROWS.trim().split(/\\s+/).map((row) => {
  const [unit = '', miss, pace] = row.split(':');

  return [unit, [Number(miss) / THOUSANDTHS, Number(pace) / THOUSANDTHS] as const];
}));
"""


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--models", required=True)
    parser.add_argument("--miss", required=True)
    parser.add_argument("--pace", required=True)
    parser.add_argument("--rate-pair", type=float, required=True)
    parser.add_argument("--rate-key", type=float, required=True)
    parser.add_argument("--out", required=True)
    args = parser.parse_args()

    with open(args.models) as file:
        models = json.load(file)

    miss, pace = models[args.miss], models[args.pace]
    rows = []

    for unit in sorted(set(miss) | set(pace), key=lambda name: (len(name), name)):
        m = round(miss.get(unit, {}).get("miss", [0])[0] * THOUSANDTHS)
        p = round(pace.get(unit, {}).get("pace", [0])[0] * THOUSANDTHS)
        rows.append(f"{unit}:{m}:{p}")

    lines = [" ".join(rows[i:i + 14]) for i in range(0, len(rows), 14)]

    with open(args.out, "w") as file:
        file.write(HEADER % (round(args.rate_pair, 5), round(args.rate_key, 5), "\n".join(lines)))


if __name__ == "__main__":
    main()
